/**
 * Golden contract for the SM-18 scheduler port (sm18-re gitlab issue #28).
 *
 * The reference lives in `sm18-re:smfmt/scheduler.py`. The fixture
 * `test/fixtures/sm18-port-scheduler.json` is a mirror of
 * `sm18-re:tests/fixtures/port-scheduler.json` and is regenerated by
 * `sm18-re:scripts/export-port-scheduler-fixture.py`. The lane re-copies the
 * mirror on every change so sm18-re's gate catches drift on either side.
 *
 * This file is brief-writer owned (gitlab issue #28). The lane implements
 * `src/sm18-scheduler.ts` with an exported `predict(state, grade)` whose
 * TypeScript signature mirrors the Python reference's. Until that module
 * exists every case `t.skip`s, so `npm test` stays green; the sm18-re side
 * gate separately checks the module file is present before counting a
 * passing run as proof the port landed.
 */

import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { join } from "node:path";

const FIXTURE_PATH = join(__dirname, "fixtures", "sm18-port-scheduler.json");
const MODULE_SPEC = ["..", "src", "sm18-scheduler.ts"].join("/");

interface SchedulerStatePrimitive {
  stability: number;
  difficulty: number;
  retrievability: number;
  interval: number;
  next_interval: number;
  elapsed: number;
  lapses: number;
  repetition: number;
  a_factor: number;
  graded: boolean;
  has_history: boolean;
  priority_position: number;
  kind: number;
  postpones: number;
}

interface FixtureCase {
  label: string;
  input: SchedulerStatePrimitive;
  grade: number;
  expected: SchedulerStatePrimitive;
}

interface Fixture {
  schema: number;
  source: string;
  cases: FixtureCase[];
}

interface PortModule {
  predict: (state: SchedulerStatePrimitive, grade: number) => SchedulerStatePrimitive;
}

async function loadPort(): Promise<PortModule | null> {
  try {
    const mod = await import(MODULE_SPEC);
    if (typeof mod?.predict !== "function") return null;
    return mod as PortModule;
  } catch {
    return null;
  }
}

const fixture: Fixture = JSON.parse(readFileSync(FIXTURE_PATH, "utf8"));

test("fixture is present and non-empty", () => {
  assert.equal(fixture.schema, 1);
  assert.ok(fixture.cases.length > 0, "fixture has cases");
});

test("src/sm18-scheduler.ts exports predict", async (t) => {
  const port = await loadPort();
  if (port === null) {
    t.skip("src/sm18-scheduler.ts not implemented yet");
    return;
  }
  assert.equal(typeof port.predict, "function");
});

for (const row of fixture.cases) {
  test(`predict reproduces: ${row.label}`, async (t) => {
    const port = await loadPort();
    if (port === null) {
      t.skip("src/sm18-scheduler.ts not implemented yet");
      return;
    }
    const actual = port.predict(row.input, row.grade);
    const numericKeys: (keyof SchedulerStatePrimitive)[] = [
      "stability", "difficulty", "retrievability",
      "interval", "next_interval", "elapsed",
      "a_factor", "priority_position",
    ];
    const integerKeys: (keyof SchedulerStatePrimitive)[] = [
      "lapses", "repetition", "kind", "postpones",
    ];
    const booleanKeys: (keyof SchedulerStatePrimitive)[] = [
      "graded", "has_history",
    ];
    for (const k of numericKeys) {
      const got = actual[k] as number;
      const want = row.expected[k] as number;
      // 1e-9 absolute: SchedulerState floats are produced by elementary ops on
      // IEEE-754 doubles the Python reference emits in the same order; drift
      // is only possible via a divergent branch, not accumulated rounding.
      assert.ok(
        Math.abs(got - want) < 1e-9,
        `${k}: got ${got}, want ${want} (|diff|=${Math.abs(got - want)})`,
      );
    }
    for (const k of integerKeys) {
      assert.equal(actual[k], row.expected[k], `${k} mismatch`);
    }
    for (const k of booleanKeys) {
      assert.equal(actual[k], row.expected[k], `${k} mismatch`);
    }
  });
}
